def replace_func(src, name, next_name, replacement):
    start_token = f'function {name}('
    end_token = f'\nfunction {next_name}('
    start = src.find(start_token)
    if start < 0:
        raise SystemExit(f'function not found: {name}')
    end = src.find(end_token, start)
    if end < 0:
        raise SystemExit(f'next function not found after {name}: {next_name}')
    return src[:start] + replacement.rstrip() + src[end:]

shell = r'''function shell(){return`<section class="ka-stack" data-management-module><div class="ka-row ka-row--between ka-management-intro" data-management-heading><div><h2>Yönetim</h2><p class="ka-muted">Personel, görev, izin ve nöbet bilgileri cihaz verisinden açılır.</p></div><span id="managementCount" class="ka-badge"></span></div><label class="ka-field ka-management-search" data-management-search-wrap><span class="ka-field__label">Ara</span><input id="managementSearch" type="search" placeholder="Personel, görev veya tarih ara…"></label><div id="managementContent" class="ka-stack"></div></section>`}'''
mgmt = replace_func(mgmt, 'shell', 'staff', shell)

# Remove the old mobile-only day-card renderer. The canonical duty view is now the table on every viewport.
start = mgmt.find('function dutyMobile(')
end = mgmt.find('\nfunction dutyGrid(', start)
if start < 0 or end < 0:
    raise SystemExit('dutyMobile block not found')
mgmt = mgmt[:start] + mgmt[end+1:]

new_grid = r'''function dutyGrid(){const places=NobetService.yerSirali(arr('nobetYerleri')),assign=arr('nobetAtamalari'),chiefs=arr('nobetciAmirleri'),holidays=arr('resmiTatiller'),days=new Date(dutyYear,dutyMonth+1,0).getDate(),rows=[],q=norm(query||''),placeCount=Math.max(1,places.length);for(let d=1;d<=days;d++){const iso=NobetService.tarihISO(dutyYear,dutyMonth,d),dt=new Date(dutyYear,dutyMonth,d),weekend=[0,6].includes(dt.getDay()),holiday=holidays.find(t=>t.tarih===iso),chief=chiefs.find(x=>x.tarih===iso),dayName=dt.toLocaleDateString('tr-TR',{weekday:'short'}).replace('.','').toLocaleUpperCase('tr'),dateLabel=dt.toLocaleDateString('tr-TR',{day:'2-digit',month:'short'}).replace('.',''),dayAssignments=assign.filter(x=>x.tarih===iso),searchText=[iso,dateLabel,dayName,holiday?.aciklama,chief?.ad,...places.map(p=>p.ad),...dayAssignments.map(a=>a.ogretmenAdSoyad)].filter(Boolean).join(' ');if(q&&!norm(searchText).includes(q))continue;if(weekend){rows.push(`<tr class="ka-duty-grid__weekend"><th scope="row"><b>${esc(dateLabel)}</b></th><td class="ka-duty-grid__day">${esc(dayName)}</td><td class="ka-duty-grid__state" colspan="${placeCount}">Hafta sonu</td><td class="ka-duty-grid__empty">—</td></tr>`);continue}if(holiday){rows.push(`<tr class="ka-duty-grid__holiday"><th scope="row"><b>${esc(dateLabel)}</b></th><td class="ka-duty-grid__day">${esc(dayName)}</td><td class="ka-duty-grid__state" colspan="${placeCount}">🎉 ${esc(holiday.aciklama||'Resmi Tatil')}</td><td class="ka-duty-grid__empty">—</td></tr>`);continue}const cells=places.length?places.map(p=>{const a=dayAssignments.find(x=>x.yerId===p.id);return`<td><button type="button" class="ka-duty-cell ${a?'filled':'empty'}" data-duty-cell="${iso}" data-duty-place="${esc(p.id)}" ${canEditDuty()?'':'disabled'}>${a?`<strong>${esc(a.ogretmenAdSoyad||'')}</strong>`:'<span>＋</span>'}</button></td>`}).join(''):'<td class="ka-duty-grid__empty">Nöbet yeri eklenmedi</td>';rows.push(`<tr><th scope="row"><b>${esc(dateLabel)}</b></th><td class="ka-duty-grid__day">${esc(dayName)}</td>${cells}<td><button type="button" class="ka-duty-cell ${chief?'filled':'empty'}" data-duty-chief="${iso}" ${canEditDuty()?'':'disabled'}>${chief?`<strong>${esc(chief.ad||'')}</strong>`:'<span>＋</span>'}</button></td></tr>`)}const placeHeaders=places.length?places.map(p=>`<th>${esc(String(p.ad||'Nöbet Yeri').toLocaleUpperCase('tr'))}</th>`).join(''):'<th>NÖBET ALANI</th>';return`<div class="ka-table-wrap ka-duty-grid-wrap" tabindex="0" aria-label="Aylık nöbet çizelgesi, yatay kaydırılabilir"><table class="ka-duty-grid"><thead><tr><th>Tarih</th><th>Gün</th>${placeHeaders}<th>Nöbetçi Amir</th></tr></thead><tbody>${rows.join('')||`<tr><td colspan="${placeCount+3}"><div class="ka-empty">Aramanızla eşleşen nöbet kaydı bulunamadı.</div></td></tr>`}</tbody></table></div>`}'''
mgmt = replace_func(mgmt, 'dutyGrid', 'duty', new_grid)

new_duty = r'''function duty(){const count=arr('nobetAtamalari').length,monthTitle=new Date(dutyYear,dutyMonth,1).toLocaleDateString('tr-TR',{month:'long',year:'numeric'}),edit=canEditDuty(),actions=`${edit?`<button class="ka-duty-action-card" type="button" data-duty-places><span class="ka-duty-action-icon">📍</span><span class="ka-duty-action-copy"><strong>Nöbet Yerleri</strong><small>Bahçe, bina ve alanlar</small></span><span class="ka-duty-action-chevron">›</span></button><button class="ka-duty-action-card" type="button" data-duty-excel><span class="ka-duty-action-icon">📥</span><span class="ka-duty-action-copy"><strong>Excel’den İçe Aktar</strong><small>Dosyadan toplu içe aktar</small></span><span class="ka-duty-action-chevron">›</span></button>`:''}<button class="ka-duty-action-card" type="button" data-duty-report><span class="ka-duty-action-icon">🖨️</span><span class="ka-duty-action-copy"><strong>Nöbet Listesi</strong><small>Çizelgeyi görüntüle ve yazdır</small></span><span class="ka-duty-action-chevron">›</span></button>${edit?`<button class="ka-duty-action-card" type="button" data-duty-auto><span class="ka-duty-action-icon">🔄</span><span class="ka-duty-action-copy"><strong>Otomatik Nöbet Dağıtımı</strong><small>Aylık dağıtımı oluştur</small></span><span class="ka-duty-action-chevron">›</span></button>`:''}`;return{count,html:`<section class="ka-stack ka-duty-page"><div class="ka-duty-action-grid">${actions}</div><div class="ka-duty-summary-grid"><article class="ka-card ka-duty-summary-card"><div class="ka-card__header"><div class="ka-duty-card-title"><span>👥</span><div><small>BUGÜN</small><h3>Bugünün Nöbetçileri</h3></div></div></div><div class="ka-card__body">${todayDutyHtml()}</div></article><article class="ka-card ka-duty-summary-card"><div class="ka-card__header ka-row ka-row--between"><div class="ka-duty-card-title"><span>📅</span><div><small>TAKVİM</small><h3>Resmi Tatiller</h3></div></div>${edit?'<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-duty-holiday-add>+ Tatil Ekle</button>':''}</div><div class="ka-card__body ka-duty-holidays">${holidaysHtml()}</div></article></div><button class="ka-duty-report-card" type="button" data-duty-report><span class="ka-duty-report-icon">📄</span><span class="ka-duty-report-copy"><strong>Öğretmen Nöbet Çizelgesi</strong><small>${esc(monthTitle)} çizelgesini görüntüleyin veya yazdırın.</small></span><span class="ka-duty-report-open">🖨 Önizle</span></button><article class="ka-card ka-duty-surface"><div class="ka-card__body"><div class="ka-duty-month"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-duty-month="-1">‹ Önceki Ay</button><h3>📅 ${esc(monthTitle)}</h3><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-duty-month="1">Sonraki Ay ›</button></div>${dutyGrid()}</div></article></section>`}}'''
mgmt = replace_func(mgmt, 'duty', 'modal', new_duty)

