if "const CACHE_ADI='oy-cache-v817';" not in sw:
    raise SystemExit('expected service worker cache v817 not found')
sw = sw.replace("const CACHE_ADI='oy-cache-v817';", "const CACHE_ADI='oy-cache-v818';", 1)

old_test = "for(const marker of ['dutyMobile','ka-duty-mobile','ka-duty-mobile-chip','ka-duty-mobile-chief','ka-duty-mobile-notice']) assert(src.includes(marker),`Mobil Nöbet görünüm sözleşmesi eksik: ${marker}`);\nassert(src.includes('${dutyMobile()}${dutyGrid()}'),'Mobil ve masaüstü Nöbet Programı aynı canonical render akışından üretilmeli.');"
new_test = "assert(!src.includes('function dutyMobile('),'Mobil gün-kartı rendererı emekliye ayrılmalı.');\nassert(!src.includes('${dutyMobile()}${dutyGrid()}'),'Nöbet Programı mobilde ayrı gün kartı rendererı kullanmamalı.');\nassert(src.includes('${dutyGrid()}'),'Aylık Nöbet Programı tüm ekranlarda canonical tablo rendererı üzerinden üretilmeli.');\nfor(const marker of ['ka-duty-action-grid','ka-duty-report-card','ka-duty-grid__day','tabindex=\\\"0\\\"','Gün']) assert(src.includes(marker),`Yeni Nöbet tablo/tasarım sözleşmesi eksik: ${marker}`);\nassert(src.includes('ka-duty-report-title')&&src.includes('ka-duty-report-table')&&src.includes('ka-duty-report-tasks'),'Yüklenen örneğe karşılık gelen nöbet rapor anatomisi korunmalı.');\nassert(src.includes('compact:true')&&src.includes('fontSize:8')&&src.includes('kenarBosluk:8'),'Nöbet raporu tek sayfalık kompakt A4 ayarlarını kullanmalı.');"
if old_test not in test:
    raise SystemExit('classic duty test marker not found')
test = test.replace(old_test, new_test, 1)

mgmt_path.write_text(mgmt, encoding='utf-8')
css_path.write_text(css, encoding='utf-8')
sw_path.write_text(sw, encoding='utf-8')
test_path.write_text(test, encoding='utf-8')

print('Duty program redesign patch applied.')
